"&gt;
  &lt;strong style="font-size: 1.1rem;"&gt;${temperatureDescription.emoji} Temperature = ${temperature.toFixed(1)}: ${temperatureDescription.text}&lt;/strong&gt;
  &lt;p style="margin: 0.5rem 0 0 0; color: #555;"&gt;${temperatureDescription.detail}&lt;/p&gt;
&lt;/div&gt;`























